AND P.category_id=#{params.categoryId}
AND P.name LIKE concat('%',#{params.searchKeyword},'%')
AND P.approval_status IN
#{state}
AND P.id IN
#{productId}
AND P.id NOT IN
#{productId}
AND p.id IN (SELECT pt.product_id FROM project_task pt WHERE 1 = 1 ${params.param})
ORDER BY pi.create_time DESC

SELECT pi.id AS productId,pi.name AS productName,pj.id AS projectId FROM product_info pi Left JOIN project_info pj ON pi.id=pj.product_id WHERE pi.delete_state=0 AND pi.is_finished_product_dev = 1 AND (pj.project_status IS NULL OR pj.project_status!=#{projectStatus})
AND pi.id NOT IN
#{archiveProductId}
